const COUNTRY_RULE_LOOKUP = new Map(COUNTRY_RULES.map((rule) => [rule.countryName.toLowerCase(), rule]));
const COUNTRY_CODE_LOOKUP = new Map(COUNTRY_RULES.map((rule) => [rule.countryCode.toLowerCase(), rule]));

export function getCountryOptions() {
  return COUNTRY_RULES.map((rule) => rule.countryName).sort((left, right) => left.localeCompare(right));
}

export function getCurrencyOptions() {
  return CURRENCY_OPTIONS.map((option) => option.code).sort((left, right) => left.localeCompare(right));
}

export function getCurrencyLabel(code?: string) {
  if (!code) return code;
  return CURRENCY_OPTIONS.find((option) => option.code === code)?.label || code;
}

export function getCountryRule(countryNameOrCode?: string) {
  if (!countryNameOrCode) {
    return COUNTRY_RULES.find((rule) => rule.countryCode === "US") || COUNTRY_RULES[0];
  }

  const normalized = countryNameOrCode.trim().toLowerCase();
  return COUNTRY_RULE_LOOKUP.get(normalized) || COUNTRY_CODE_LOOKUP.get(normalized) || COUNTRY_RULES.find((rule) => rule.countryCode === "US") || COUNTRY_RULES[0];
}
